mapper.select:
/* saleson.shop.qna.QnaMapper.getQnaListByParam */
SELECT Q.QNA_ID, Q.QNA_GROUP, Q.QNA_TYPE, Q.SUBJECT, Q.QUESTION, Q.USER_ID, Q.SELLER_ID, Q.ITEM_ID, Q.ORDER_CODE, Q.ANSWER_COUNT, Q.SECRET_FLAG, Q.DISPLAY_FLAG, Q.CREATED_DATE, Q.DATA_STATUS_CODE, Q.QNA_IMAGE, Q.USE_YN, QA.*, I.ITEM_NAME, I.ITEM_USER_CODE, I.ITEM_IMAGE, CRYPTO_DEC('normal', S.SELLER_NAME, '', 0) AS SELLER_NAME, S.COMPANY_NAME AS SELLER_COMPANY_NAME, ( SELECT CASE WHEN LOCGOV.LOCGOV_CODE = LOCGOV.UPPER_LOCGOV_CODE THEN LOCGOV.UPPER_LOCGOV_NM ELSE CONCAT(LOCGOV.UPPER_LOCGOV_NM, ' ', LOCGOV.LOCGOV_NM) END FROM G_LOCGOV LOCGOV WHERE LOCGOV.LOCGOV_CODE = S.LOCGOV_CODE ) AS LOCGOV_NAME, ROWNUM, CRYPTO_DEC('normal',Q.LOGIN_ID, '', 0) as LOGIN_ID, CRYPTO_DEC('normal',Q.USER_NAME, '', 0) as USER_NAME, CRYPTO_DEC('normal',Q.EMAIL, '', 0) as EMAIL, CASE WHEN (SELECT COUNT(1) FROM OP_SELLER_USER OSU WHERE OSU.USER_ID = QA.USER_ID) = 0 AND QA.USER_ID IS NOT NULL THEN 'ADMIN' ELSE NULL END AS ROLE_NM FROM (
SELECT
Q.QNA_ID, Q.QNA_GROUP, Q.QNA_TYPE, Q.SUBJECT, Q.QUESTION, Q.USER_ID, Q.SELLER_ID, Q.ITEM_ID, Q.ORDER_CODE, Q.ANSWER_COUNT, Q.SECRET_FLAG, Q.DISPLAY_FLAG, Q.CREATED_DATE, Q.DATA_STATUS_CODE, Q.QNA_IMAGE, Q.USE_YN, U.LOGIN_ID, Q.USER_NAME, Q.EMAIL FROM OP_QNA Q LEFT JOIN OP_USER U ON Q.USER_ID = U.USER_ID AND U.STATUS_CODE = '9' LEFT JOIN OP_COMMON_CODE C ON C.ID = Q.QNA_GROUP AND C.CODE_TYPE = 'QNA_GROUPS' AND C.USE_YN = 'Y' WHERE Q.DATA_STATUS_CODE = '0' AND Q.DISPLAY_FLAG = 'Y'
AND Q.QNA_GROUP = #{qnaGroup}
AND Q.QNA_TYPE = #{qnaType}
AND Q.ITEM_ID = #{itemId}
AND Q.USER_ID = #{userId}
AND Q.CREATED_DATE >= CONCAT(#{searchStartDate}, '000000')
AND Q.CREATED_DATE <= CONCAT(#{searchEndDate}, '235959')
AND Q.SELLER_ID = #{sellerId}
AND Q.ANSWER_COUNT > 0
AND Q.ANSWER_COUNT = 0
AND ( SELECT COUNT(1) FROM OP_QNA_ANSWER WHERE QNA_ID = Q.QNA_ID ) > 0
AND ( SELECT COUNT(1) FROM OP_QNA_ANSWER WHERE QNA_ID = Q.QNA_ID ) = 0
AND Q.USER_NAME = (SELECT crypto_enc('normal', #{query},''))
AND U.LOGIN_ID LIKE CONCAT('%', crypto_enc('normal', #{query}, '') , '%')
AND Q.EMAIL = (SELECT crypto_enc('normal', #{query},''))
AND Q.SUBJECT LIKE CONCAT('%', #{query} , '%')
AND Q.QUESTION LIKE CONCAT('%', #{query} , '%')
AND C.LABEL LIKE CONCAT('%', #{query} , '%')
AND Q.DISPLAY_FLAG = #{displayFlag}
AND Q.USE_YN = #{useYn}
ORDER BY Q.CREATED_DATE DESC
) Q LEFT JOIN OP_QNA_ANSWER QA ON Q.QNA_ID = QA.QNA_ID LEFT JOIN OP_ITEM I ON Q.ITEM_ID = I.ITEM_ID LEFT JOIN OP_SELLER S ON S.SELLER_ID = Q.SELLER_ID
AND I.ITEM_NAME LIKE CONCAT('%', #{query} , '%')
AND Q.SUBJECT LIKE CONCAT('%', #{query} , '%')
AND I.ITEM_CODE LIKE CONCAT('%', #{query} , '%')
AND I.ITEM_USER_CODE LIKE CONCAT('%', #{query} , '%')
AND S.COMPANY_NAME LIKE CONCAT('%', #{query} , '%')
AND S.LOCGOV_CODE = #{sigungu}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{sido} )

/* saleson.shop.qna.QnaMapper.getQnaListCountByParam */
SELECT COUNT(*) AS CNT FROM (
SELECT
Q.QNA_ID, Q.QNA_GROUP, Q.QNA_TYPE, Q.SUBJECT, Q.QUESTION, Q.USER_ID, Q.SELLER_ID, Q.ITEM_ID, Q.ORDER_CODE, Q.ANSWER_COUNT, Q.SECRET_FLAG, Q.DISPLAY_FLAG, Q.CREATED_DATE, Q.DATA_STATUS_CODE, Q.QNA_IMAGE, Q.USE_YN, U.LOGIN_ID, Q.USER_NAME, Q.EMAIL FROM OP_QNA Q LEFT JOIN OP_USER U ON Q.USER_ID = U.USER_ID AND U.STATUS_CODE = '9' LEFT JOIN OP_COMMON_CODE C ON C.ID = Q.QNA_GROUP AND C.CODE_TYPE = 'QNA_GROUPS' AND C.USE_YN = 'Y' WHERE Q.DATA_STATUS_CODE = '0' AND Q.DISPLAY_FLAG = 'Y'
AND Q.QNA_GROUP = #{qnaGroup}
AND Q.QNA_TYPE = #{qnaType}
AND Q.ITEM_ID = #{itemId}
AND Q.USER_ID = #{userId}
AND Q.CREATED_DATE >= CONCAT(#{searchStartDate}, '000000')
AND Q.CREATED_DATE <= CONCAT(#{searchEndDate}, '235959')
AND Q.SELLER_ID = #{sellerId}
AND Q.ANSWER_COUNT > 0
AND Q.ANSWER_COUNT = 0
AND ( SELECT COUNT(1) FROM OP_QNA_ANSWER WHERE QNA_ID = Q.QNA_ID ) > 0
AND ( SELECT COUNT(1) FROM OP_QNA_ANSWER WHERE QNA_ID = Q.QNA_ID ) = 0
AND Q.USER_NAME = (SELECT crypto_enc('normal', #{query},''))
AND U.LOGIN_ID LIKE CONCAT('%', crypto_enc('normal', #{query}, '') , '%')
AND Q.EMAIL = (SELECT crypto_enc('normal', #{query},''))
AND Q.SUBJECT LIKE CONCAT('%', #{query} , '%')
AND Q.QUESTION LIKE CONCAT('%', #{query} , '%')
AND C.LABEL LIKE CONCAT('%', #{query} , '%')
AND Q.DISPLAY_FLAG = #{displayFlag}
AND Q.USE_YN = #{useYn}
ORDER BY Q.CREATED_DATE DESC
) Q LEFT JOIN OP_QNA_ANSWER QA ON Q.QNA_ID = QA.QNA_ID LEFT JOIN OP_ITEM I ON Q.ITEM_ID = I.ITEM_ID LEFT JOIN OP_SELLER S ON S.SELLER_ID = Q.SELLER_ID
AND I.ITEM_NAME LIKE CONCAT('%', #{query} , '%')
AND Q.SUBJECT LIKE CONCAT('%', #{query} , '%')
AND I.ITEM_CODE LIKE CONCAT('%', #{query} , '%')
AND I.ITEM_USER_CODE LIKE CONCAT('%', #{query} , '%')
AND S.COMPANY_NAME LIKE CONCAT('%', #{query} , '%')
AND S.LOCGOV_CODE = #{sigungu}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{sido} )

/* saleson.shop.qna.QnaMapper.getQnaAnswerListByQnaId */
SELECT
	QA.*
FROM OP_QNA_ANSWER QA
WHERE QA.QNA_ID = #{qnaId}

