mapper.select:
/* saleson.shop.qna.QnaMapper.getFrontQnaOpenDetail */ WITH TEMP_QNA_TABLE AS ( SELECT ROWNUM AS RNUM, X.QNA_ID, X.QNA_ANSWER_ID, X.CREATED_DATE, X.QNA_USER_ID, X.USER_ID, crypto_dec('normal', X.USER_NAME, '', 0) USER_NAME, X.QNA_DETAIL_TYPE, X.SUBJECT, X.HITS, X.QNA_SECRET_FLAG, X.SECRET_FLAG, X.QUESTION, X.ANSWER_COUNT, X.QNA_GROUP FROM ( SELECT A.QNA_ID, A.QNA_ANSWER_ID, A.CREATED_DATE, A.QNA_USER_ID, A.USER_ID, A.USER_NAME, A.QNA_DETAIL_TYPE, A.SUBJECT, A.HITS, A.QNA_SECRET_FLAG, A.SECRET_FLAG, A.QUESTION, A.ANSWER_COUNT, A.QNA_GROUP FROM ( SELECT QNA_ID, NULL AS QNA_ANSWER_ID, CREATED_DATE, USER_ID AS QNA_USER_ID, USER_ID, USER_NAME, 'Q' AS QNA_DETAIL_TYPE, SUBJECT, HITS, SECRET_FLAG AS QNA_SECRET_FLAG, SECRET_FLAG, QUESTION, ANSWER_COUNT, QNA_GROUP FROM OP_QNA WHERE QNA_TYPE = 2 AND DATA_STATUS_CODE = 0 AND DISPLAY_FLAG = 'Y' AND USE_YN = 'Y'
UNION ALL
SELECT QA.QNA_ID, QA.QNA_ANSWER_ID, QA.ANSWER_DATE, Q.USER_ID AS QNA_USER_ID, QA.USER_ID, IFNULL(M.USER_NAME, U.USER_NAME) AS USER_NAME, 'A' AS QNA_DETAIL_TYPE, QA.TITLE, QA.HITS, Q.SECRET_FLAG AS QNA_SECRET_FLAG, QA.SECRET_FLAG, QA.ANSWER, 0 AS ANSWER_COUNT, Q.QNA_GROUP FROM OP_QNA_ANSWER QA INNER JOIN OP_QNA Q ON Q.QNA_ID = QA.QNA_ID AND Q.QNA_TYPE = 2 AND Q.DATA_STATUS_CODE = 0 AND Q.DISPLAY_FLAG = 'Y' AND Q.USE_YN = 'Y' LEFT OUTER JOIN OP_MANAGER M ON M.USER_ID = QA.USER_ID LEFT OUTER JOIN OP_USER U ON U.USER_ID = QA.USER_ID WHERE QA.DATA_STATUS_CODE = 0 ) A ORDER BY A.QNA_ID DESC, IFNULL(A.QNA_ANSWER_ID, 0) ) X ) SELECT * ,(SELECT CONCAT(IFNULL(QNA_ID, 0), '|', IFNULL(QNA_ANSWER_ID, 0), '|', IFNULL(SUBJECT, ''), '|', IFNULL(QNA_SECRET_FLAG, '')) FROM TEMP_QNA_TABLE WHERE RNUM < A.RNUM ORDER BY RNUM DESC LIMIT 1) AS NEXT_QNA_INFO ,(SELECT CONCAT(IFNULL(QNA_ID, 0), '|', IFNULL(QNA_ANSWER_ID, 0), '|', IFNULL(SUBJECT, ''), '|', IFNULL(QNA_SECRET_FLAG, '')) FROM TEMP_QNA_TABLE WHERE RNUM > A.RNUM ORDER BY RNUM ASC LIMIT 1) AS PREV_QNA_INFO FROM TEMP_QNA_TABLE A WHERE A.QNA_ID = #{qnaId} AND IFNULL(A.QNA_ANSWER_ID, 0) = IFNULL(#{qnaAnswerId}, 0) LIMIT 1

mapper.update:
/** qna-mapper.addQnaHitCount (QNA 조회수 증가) */
UPDATE OP_QNA
SET HITS = HITS + 1
WHERE QNA_ID = #{qnaId}

/** qna-mapper.addQnaAnswerHitCount (QNA 답변 조회수 증가) */
UPDATE OP_QNA_ANSWER
SET HITS = HITS + 1
WHERE QNA_ID = #{qnaId}
AND QNA_ANSWER_ID = #{qnaAnswerId}

