/* saleson.shop.qna.QnaMapper.insertQnaAnswerFile */
INSERT INTO OP_QNA_ANSWER_FILE (
	QNA_ANSWER_FILE_ID
	, QNA_ANSWER_ID
	, FILE_NAME
	, FILE_TY
	, ORDERING
	, CREATED_DATE
	, ORG_FILE_NAME
) VALUES (
	#{qnaFileId}
	, #{qnaId}
	, #{fileName}
	, #{fileTy}
	, (SELECT IFNULL(MAX(ORDERING)+1, 1) FROM OP_QNA_ANSWER_FILE WHERE QNA_ANSWER_ID = #{qnaId})
	, 
	, #{orgFileName}
)

mapper.select:
/* saleson.shop.qna.QnaMapper.getFiveMinuteCheck */
select count(created_date) as cnt
  from OP_QNA
 where user_id = #{userId}
   and (to_datetime(created_date, 'YYYYMMDDHH24MISS') >= ADDDATE(SYS_DATETIME, INTERVAL - 5 MINUTE))
   and use_yn='Y' order by created_date desc limit 1
